<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban Board</title>
<style>
  :root {
    --bg: #f1f4f9;
    --panel: #ffffff;
    --panel-alt: #f7f9fc;
    --border: #e2e8f0;
    --text: #1e293b;
    --muted: #64748b;
    --accent: #4f46e5;
    --accent-soft: #eef2ff;
    --shadow: 0 1px 2px rgba(15, 23, 42, .06), 0 4px 12px rgba(15, 23, 42, .06);
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
  }
  header.app {
    padding: 28px 32px 12px;
    max-width: 1180px;
    margin: 0 auto;
  }
  header.app h1 {
    margin: 0 0 4px;
    font-size: 26px;
    letter-spacing: -.02em;
  }
  header.app p {
    margin: 0;
    color: var(--muted);
    font-size: 14px;
  }
  .composer {
    max-width: 1180px;
    margin: 18px auto 0;
    padding: 0 32px;
    display: flex;
    gap: 10px;
  }
  #new-card {
    flex: 1;
    padding: 11px 14px;
    font: inherit;
    color: var(--text);
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card::placeholder { color: #9aa5b6; }
  #new-card:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(79, 70, 229, .15);
  }
  #add-card {
    padding: 11px 20px;
    font: inherit;
    font-weight: 600;
    color: #fff;
    background: var(--accent);
    border: 0;
    border-radius: 10px;
    cursor: pointer;
    transition: background .15s, transform .05s;
  }
  #add-card:hover { background: #4338ca; }
  #add-card:active { transform: translateY(1px); }

  .board {
    max-width: 1180px;
    margin: 0 auto;
    padding: 22px 32px 48px;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    align-items: start;
  }
  @media (max-width: 820px) {
    .board { grid-template-columns: 1fr; }
  }
  .column {
    background: var(--panel-alt);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 14px;
    min-height: 220px;
    display: flex;
    flex-direction: column;
    transition: background .15s, border-color .15s, box-shadow .15s;
  }
  .column.drag-over {
    background: var(--accent-soft);
    border-color: var(--accent);
    box-shadow: inset 0 0 0 1px var(--accent);
  }
  .col-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 12px;
    padding: 0 4px;
  }
  .col-head h2 {
    margin: 0;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: .07em;
    text-transform: uppercase;
    color: var(--muted);
  }
  .count {
    min-width: 24px;
    padding: 2px 8px;
    text-align: center;
    font-size: 12px;
    font-weight: 700;
    color: var(--accent);
    background: var(--accent-soft);
    border-radius: 999px;
  }
  .cards {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 80px;
  }
  .card {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 12px 12px 14px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    box-shadow: var(--shadow);
    cursor: grab;
    transition: transform .12s, box-shadow .12s, opacity .12s;
  }
  .card:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 4px rgba(15, 23, 42, .07), 0 8px 18px rgba(15, 23, 42, .08);
  }
  .card.dragging { opacity: .45; cursor: grabbing; }
  .card-title {
    flex: 1;
    word-break: break-word;
    white-space: pre-wrap;
  }
  .card-del {
    flex: none;
    width: 24px;
    height: 24px;
    line-height: 1;
    font-size: 15px;
    color: var(--muted);
    background: transparent;
    border: 0;
    border-radius: 6px;
    cursor: pointer;
    transition: background .15s, color .15s;
  }
  .card-del:hover { background: #fee2e2; color: #dc2626; }
  .empty {
    padding: 14px 4px;
    font-size: 13px;
    color: #9aa5b6;
    text-align: center;
  }
</style>
</head>
<body>

<header class="app">
  <h1>Kanban Board</h1>
  <p>Add a card, drag it between columns. Everything saves locally.</p>
</header>

<div class="composer">
  <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off">
  <button id="add-card" type="button">Add card</button>
</div>

<main class="board">
  <section class="column" id="col-todo" data-col="todo">
    <div class="col-head"><h2>To Do</h2><span class="count">0</span></div>
    <div class="cards" data-cards></div>
  </section>
  <section class="column" id="col-doing" data-col="doing">
    <div class="col-head"><h2>Doing</h2><span class="count">0</span></div>
    <div class="cards" data-cards></div>
  </section>
  <section class="column" id="col-done" data-col="done">
    <div class="col-head"><h2>Done</h2><span class="count">0</span></div>
    <div class="cards" data-cards></div>
  </section>
</main>

<script>
(function () {
  var STORAGE_KEY = 'kanban.board.v1';
  var COLS = ['todo', 'doing', 'done'];

  var input = document.getElementById('new-card');
  var addBtn = document.getElementById('add-card');

  /* state: [{id, title, col}] */
  var state = load();
  var seq = 0;

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (c) {
        return c && typeof c.title === 'string' && COLS.indexOf(c.col) !== -1;
      }).map(function (c) {
        return { id: String(c.id || nextId()), title: c.title, col: c.col };
      });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) { /* storage unavailable — board still works in-session */ }
  }

  function nextId() {
    seq += 1;
    return 'c' + Date.now().toString(36) + seq.toString(36);
  }

  function colEl(col) { return document.getElementById('col-' + col); }

  function buildCard(card) {
    var el = document.createElement('div');
    el.className = 'card';
    el.setAttribute('draggable', 'true');
    el.dataset.id = card.id;

    var title = document.createElement('span');
    title.className = 'card-title';
    title.textContent = card.title;

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'card-del';
    del.textContent = '\u00d7';
    del.title = 'Delete card';
    del.setAttribute('aria-label', 'Delete card');

    el.appendChild(title);
    el.appendChild(del);
    return el;
  }

  function render() {
    COLS.forEach(function (col) {
      var host = colEl(col).querySelector('[data-cards]');
      host.innerHTML = '';
      var items = state.filter(function (c) { return c.col === col; });
      items.forEach(function (c) { host.appendChild(buildCard(c)); });
      if (!items.length) {
        var empty = document.createElement('div');
        empty.className = 'empty';
        empty.textContent = 'Drop cards here';
        host.appendChild(empty);
      }
      colEl(col).querySelector('.count').textContent = String(items.length);
    });
  }

  function addCard() {
    var text = input.value.trim();
    if (!text) return;
    state.push({ id: nextId(), title: text, col: 'todo' });
    input.value = '';
    save();
    render();
    input.focus();
  }

  addBtn.addEventListener('click', addCard);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); addCard(); }
  });

  /* delete (event-delegated so it survives re-render) */
  document.addEventListener('click', function (e) {
    var btn = e.target.closest ? e.target.closest('.card-del') : null;
    if (!btn) return;
    var card = btn.closest('.card');
    if (!card) return;
    var id = card.dataset.id;
    state = state.filter(function (c) { return c.id !== id; });
    save();
    render();
  });

  /* ---------- HTML5 drag & drop ---------- */
  var draggingId = null;

  document.addEventListener('dragstart', function (e) {
    var card = e.target.closest ? e.target.closest('.card') : null;
    if (!card) return;
    draggingId = card.dataset.id;
    card.classList.add('dragging');
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = 'move';
      try { e.dataTransfer.setData('text/plain', draggingId); } catch (err) {}
    }
  });

  document.addEventListener('dragend', function (e) {
    var card = e.target.closest ? e.target.closest('.card') : null;
    if (card) card.classList.remove('dragging');
    draggingId = null;
    COLS.forEach(function (col) { colEl(col).classList.remove('drag-over'); });
  });

  COLS.forEach(function (col) {
    var zone = colEl(col);

    zone.addEventListener('dragover', function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      zone.classList.add('drag-over');
    });

    zone.addEventListener('dragenter', function (e) {
      e.preventDefault();
      zone.classList.add('drag-over');
    });

    zone.addEventListener('dragleave', function (e) {
      if (!zone.contains(e.relatedTarget)) zone.classList.remove('drag-over');
    });

    zone.addEventListener('drop', function (e) {
      e.preventDefault();
      e.stopPropagation();
      zone.classList.remove('drag-over');

      var id = draggingId;
      if (!id && e.dataTransfer) {
        try { id = e.dataTransfer.getData('text/plain'); } catch (err) { id = null; }
      }
      if (!id) return;

      var moved = false;
      state = state.map(function (c) {
        if (c.id === id && c.col !== col) { moved = true; return { id: c.id, title: c.title, col: col }; }
        return c;
      });
      // move to end of target column's ordering
      if (moved) {
        var idx = state.findIndex(function (c) { return c.id === id; });
        if (idx > -1) state.push(state.splice(idx, 1)[0]);
        save();
      }
      draggingId = null;
      render();
    });
  });

  render();
})();
</script>
</body>
</html>
